BeginPlay()
{
    ShowUI(HUD);

    CreateAgent(Day)
        .Team(Morninghollow.Day)
        .Bot(DefaultBot)
        .Resources(StartingResources);

    CreateAgent(Night)
        .Team(Morninghollow.Night)
        .Bot(DefaultBot)
        .Resources(StartingResources);

    Spawn(Stargate)
        .Location(-100, 0, 0)
        .Owner(Day);

    Spawn(Stargate)
        .Location(100, 0, 0)
        .Owner(Night);
}
